<script setup lang="ts">
import {computed,nextTick,onUnmounted,ref,watch} from 'vue';
import {ArrowDown,ArrowUp,Check,ChevronDown,Files,FileText,Search,ShieldCheck,X} from 'lucide-vue-next';
import {MAX_TASK_ATTACHMENTS,moveTaskAttachment,orderedTaskAttachments,taskAttachmentIds,taskAttachmentLabel} from '../lib/task-attachments';
const props=withDefaults(defineProps<{files:Record<string,any>[];modelValue:string[]|null;disabled?:boolean}>(),{disabled:false});
const emit=defineEmits<{'update:modelValue':[ids:string[]|null];opened:[value:boolean]}>();
const open=ref(false);const query=ref('');const draft=ref<string[]>([]);const dialog=ref<HTMLElement|null>(null);const search=ref<HTMLInputElement|null>(null);let previous:HTMLElement|null=null;
const files=computed(()=>orderedTaskAttachments(props.files));
const selected=computed(()=>taskAttachmentIds(files.value,props.modelValue));
const unavailable=computed(()=>draft.value.filter(id=>!files.value.some(file=>file.id===id)).length);
const shown=computed(()=>{
 const ordered=[...draft.value.map(id=>files.value.find(file=>file.id===id)).filter(Boolean),...files.value.filter(file=>!draft.value.includes(file.id))] as Record<string,any>[];
 const term=query.value.trim().toLocaleLowerCase('pt-BR');return term?ordered.filter(file=>file.name.toLocaleLowerCase('pt-BR').includes(term)):ordered;
});
const summary=computed(()=>!selected.value.length?'Sem anexos novos':selected.value.length+' '+(selected.value.length===1?'arquivo':'arquivos')+' no pedido');
function openPicker(){if(props.disabled)return;previous=document.activeElement as HTMLElement|null;draft.value=[...selected.value];query.value='';open.value=true;}
function close(){open.value=false;}
function toggle(id:string){if(draft.value.includes(id))draft.value=draft.value.filter(item=>item!==id);else if(draft.value.length<MAX_TASK_ATTACHMENTS)draft.value=[...draft.value,id];}
function apply(){if(unavailable.value||draft.value.length>MAX_TASK_ATTACHMENTS)return;emit('update:modelValue',[...draft.value]);close();}
function keydown(event:KeyboardEvent){event.stopPropagation();if(event.key==='Escape'){event.preventDefault();close();return;}if(event.key!=='Tab')return;const items=[...dialog.value?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),summary,a[href],[tabindex="0"]')??[]].filter(item=>item.getClientRects().length);const first=items[0],last=items.at(-1);if(!first){event.preventDefault();return;}if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}
watch(open,async value=>{emit('opened',value);await nextTick();if(value)search.value?.focus();else if(previous?.isConnected)previous.focus({preventScroll:true});});
onUnmounted(()=>{if(open.value){emit('opened',false);if(previous?.isConnected)previous.focus({preventScroll:true});}});
</script>
<template>
 <span class="task-attachment-control">
  <button type="button" class="task-attachment-trigger" :disabled="disabled" :aria-label="'Escolher arquivos para o pedido: '+summary" :title="summary" data-tour="project-attachment-selection" @click="openPicker"><Files :size="15"/><span>Arquivos</span><strong>{{selected.length}}</strong></button>
  <Teleport to="body"><div v-if="open" class="modal-backdrop task-attachment-backdrop" @click.self="close"><section ref="dialog" class="task-attachment-dialog" role="dialog" aria-modal="true" aria-labelledby="task-attachment-title" aria-describedby="task-attachment-description" @keydown="keydown">
   <header><span class="task-attachment-icon"><Files :size="23"/></span><div><small>REFERÊNCIAS PARA A IA</small><h2 id="task-attachment-title">Arquivos deste pedido</h2><p id="task-attachment-description">Escolha até 12 arquivos do projeto para o próximo envio.</p></div><button class="icon-button" type="button" aria-label="Fechar seleção de arquivos" @click="close"><X :size="19"/></button></header>
   <div class="task-attachment-tools"><label><Search :size="16"/><input ref="search" v-model="query" type="search" aria-label="Buscar arquivo no projeto" placeholder="Buscar arquivo…"></label><div><strong aria-live="polite">{{draft.length}} de {{MAX_TASK_ATTACHMENTS}}</strong><button type="button" @click="draft=taskAttachmentIds(files,null)">Usar padrão</button><button type="button" @click="draft=[]">Sem anexos</button></div></div>
   <div class="task-attachment-list">
   <p v-if="files.length>MAX_TASK_ATTACHMENTS" class="task-attachment-notice">O projeto tem {{files.length}} anexos. Selecione as referências mais úteis. Desmarque um dos escolhidos para incluir outro.</p>
   <p v-if="unavailable" class="task-attachment-warning" role="alert">{{unavailable}} arquivo(s) da seleção ficaram indisponíveis. Use o padrão ou limpe a seleção para escolher novamente.</p>
    <details class="task-attachment-limits"><summary aria-label="Limites de leitura e contexto dos anexos"><ShieldCheck :size="16"/><span>Até 3 imagens ou páginas de PDF</span><ChevronDown :size="15"/></summary><p>As páginas e imagens seguem a ordem escolhida. Use as setas para priorizar uma referência.<br><span>A seleção vale para este envio e suas retomadas. Conteúdo já enviado pode continuar na memória da conversa; para outro contexto, abra uma nova conversa. Os arquivos continuam salvos no projeto.</span></p></details>
    <article v-for="file in shown" :key="file.id" class="task-attachment-row" :class="{selected:draft.includes(file.id)}"><label><input type="checkbox" :checked="draft.includes(file.id)" :disabled="!draft.includes(file.id)&&draft.length>=MAX_TASK_ATTACHMENTS" :aria-label="'Usar '+file.name+' neste pedido'" @change="toggle(file.id)"><span class="task-attachment-order"><span v-if="draft.includes(file.id)">{{draft.indexOf(file.id)+1}}</span><FileText v-else :size="17"/></span><span class="task-attachment-name"><strong :title="file.name">{{file.name}}</strong><small :class="{failed:['failed','empty'].includes(file.metadata?.extraction?.status)}">{{taskAttachmentLabel(file)}}</small></span></label><span v-if="draft.includes(file.id)" class="task-attachment-priority"><button type="button" class="icon-button" :disabled="draft.indexOf(file.id)===0" :aria-label="'Priorizar '+file.name" title="Mover para cima" @click="draft=moveTaskAttachment(draft,file.id,-1)"><ArrowUp :size="15"/></button><button type="button" class="icon-button" :disabled="draft.indexOf(file.id)===draft.length-1" :aria-label="'Mover '+file.name+' para baixo'" title="Mover para baixo" @click="draft=moveTaskAttachment(draft,file.id,1)"><ArrowDown :size="15"/></button></span></article>
    <div v-if="!shown.length" class="task-attachment-empty"><FileText :size="27"/><strong>{{files.length?'Nenhum arquivo encontrado':'Envie sua primeira referência'}}</strong><p>{{files.length?'Tente buscar por outro nome.':'Use o clipe da conversa para anexar um arquivo ao projeto.'}}</p></div>
   </div>
   <footer><span>{{draft.length?'Seleção pronta para o próximo pedido':'O próximo pedido ficará sem anexos novos'}}</span><button type="button" class="primary-button" :disabled="!!unavailable||draft.length>MAX_TASK_ATTACHMENTS" @click="apply"><Check :size="16"/> Usar seleção</button></footer>
  </section></div></Teleport>
 </span>
</template>
